-- 시스템관리 > 이메일 설정(/mail-config) AS-IS 등록 콘텐츠 3건 적재 (2026-10-07).
--
-- AS-IS OP_MAIL_CONFIG는 템플릿 10종 중 대부분이 미등록(행 없음)이고, 사용자가 CUBRID
-- 개발DB에서 직접 export한 OP_MAIL_CONFIG_202610071417.sql 기준으로 실제 제목+본문이
-- 등록돼 있는 건 3종뿐이다: expiration_point(포인트소멸예정)·manager_request_approval
-- (관리자 권한 승인)·manager_request_reject(관리자 권한 거절). 셀 셋 다 BUYER_SEND_FLAG=
-- ADMIN_SEND_FLAG='N'(미발송)까지 AS-IS 그대로다 - 발송을 켜는 건 이 작업 범위가 아니다.
--
-- 재실행 안전: 이 3개 템플릿 기존 행을 지우고 다시 넣는다(admin/mail-config 화면에서
-- order_deposit_wait용으로 만든 사용자 테스트행 등 다른 템플릿은 건드리지 않는다).

DELETE FROM admin.op_mail_config
 WHERE template_id IN ('expiration_point', 'manager_request_approval', 'manager_request_reject');

INSERT INTO admin.op_mail_config
    (sms_config, template_id, title, buyer_subject, admin_subject, seller_subject,
     buyer_content, admin_content, seller_content, buyer_send_flag, admin_send_flag,
     seller_send_flag, buyer_tag_use, admin_tag_use, seller_tag_use, created_date,
     mobile_buyer_subject, mobile_admin_subject, mobile_seller_subject,
     mobile_buyer_content, mobile_admin_content, mobile_seller_content) VALUES
	 (NULL,'expiration_point','포인트소멸예정','【{site_name}】 포인트 소멸 안내 메일입니다.',NULL,NULL,'<span style="font-size: 14px;"><meta charset="UTF-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>고향사랑관리자</title><meta charset="UTF-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>고향사랑 관리자</title><meta charset="UTF-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>고향사랑 관리자</title><meta charset="UTF-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>고향사랑 관리자</title><meta charset="UTF-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>고향사랑 관리자</title><meta charset="UTF-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>고향사랑 관리자</title><table width="100%" cellspacing="0" cellpadding="0" border="0" style="font-family:''Noto Sans KR'',-apple-system,BlinkMacSystemFont,system-ui,Roboto,''Helvetica Neue'',''Segoe UI'',''Apple SD Gothic Neo'',,''Malgun Gothic'',sans-serif; font-size:14px; line-height:1; font-weight:400;vertical-align:top; word-wrap: break-word; word-break: break-all; box-sizing: border-box;"><tbody><tr><td><table align="center" style="width:760px; border:5px solid #d6d6d6; border-collapse:collapse; margin: 0 auto;"><thead><tr><td style="padding:25px 25px 55px"><h1 style="margin:0; text-align:left;"><a style="display:block;" href="https://www.ilovegohyang.go.kr" title="고향사랑이음"><img style="border:0;width: 190px;height: 38px;" src="https://www.ilovegohyang.go.kr/content/opmanager/images/img_logo_02.png" alt="고향사랑이음 로고"></a></h1></td></tr></thead><tbody><tr><td style="padding:0 36px 20px; text-align:center;"><h2 style="margin:0; font-size:34px; line-height:45px; font-weight:bold; color:#1c2957">포인트 소멸예정 안내 메일입니다.</h2></td></tr><tr><td style="padding:0 36px; text-align:center;"><p style="margin:0">아래 내역을 확인하신 후, 소멸기간 전에 포인트를 사용하세요!</p></td></tr><tr><td style="padding:40px 36px 0"><ul style="margin:0; padding:30px 0; background:#f7f7f7; font-size:14px; color:#4c4c4c; text-align:center; list-style:none"><p style="margin:0 0 20px;font-weight: bold;font-size: 16px;">{name} 회원님, 안녕하세요!</p><li style="display:inline-block">회원님께서 보유하고 계신 <span style="font-weight: bold;">포인트가 90일 후 소멸될 예정</span>입니다.</li><li style="display:inline-block;margin-top: 10px;">회원님의 포인트가 자동소멸 되는 일이 없도록 소멸일자 전에 사용하시기 바랍니다.</li></ul></td></tr><tr><td style="padding:60px 36px 0"><p style="margin:0 0 20px;font-size: 20px;font-weight: bold;">소멸 대상 혜택</p></td></tr><tr><td style="padding:0 36px"><div style="margin:0; padding:20px 30px; background:#f7f7f7; font-size:14px; color:#4c4c4c;"><p style="margin-bottom: 20px;">- 사용하지 않은 포인트: 총 <span style="color: #1b609a; font-weight: bold;">{expiration_point}P</span></p><p>- 소멸 일자 : <span style="font-weight: bold;">{expiration_date}</span></p></div></td></tr><tr><td style="padding:0 36px"><p style="margin:20px 0 0;">본 메일은 <span style="font-weight: bold;">{search_date}</span> 조회를 기준으로 안내 드립니다.</p></td></tr><tr><td style="padding:100px 36px 0;text-align: center;"><a href="https://www.ilovegohyang.go.kr" style="display:inline-block; padding: 20px; background:#333; font-size:17px; color:#fff; font-weight:bold; text-decoration:none;">{site_name} 방문하기</a></td></tr></tbody><tfoot><tr><td style="padding:30px 36px 30px; line-height:18px; text-align:center"><div style="padding:20px; background:#f5f5f5;font-size: 12px;"><p style="margin-top:4px;">본 메일은 발신전용으로 회신되지 않습니다.</p><p style="margin-top:4px;">이 안내는 관련 정책에 따라 E-Mail 수신 동의 여부와 관계없이 발송됩니다.</p></div></td></tr><tr><td style="padding:20px 36px 0; line-height:18px; color:#959595; text-align:center; letter-spacing:-1px;font-size: 12px;"><p style="margin:0">30128 세종특별자치시 정부2청사로 13(나성동)<span style="padding:0px 6px; color:#bbb; font-size:10px">|</span>30116 세종특별자치시 한누리대로 411(어진동)<span style="padding:0px 6px; color:#bbb; font-size:10px">|</span>고객센터 1522-2431</p></td></tr><tr><td style="padding:0 36px 35px; line-height:18px; color:#959595; text-align:center; letter-spacing:-1px;font-size: 12px;"><p style="margin:7px 0 0 0; color:#b0b0b0">© Ministry of the interior and safety. All rights reserved.</p></td></tr></tfoot></table></td></tr></tbody></table><table width="100%" cellspacing="0" cellpadding="0" border="0" style="font-family:''Noto Sans KR'',-apple-system,BlinkMacSystemFont,system-ui,Roboto,''Helvetica Neue'',''Segoe UI'',''Apple SD Gothic Neo'',,''Malgun Gothic'',sans-serif; font-size:14px; line-height:1; font-weight:400;vertical-align:top; word-wrap: break-word; word-break: break-all; box-sizing: border-box;"><tbody></tbody></table></span><br>',NULL,NULL,'N','N',NULL,NULL,NULL,NULL,'20221219133558',NULL,NULL,NULL,NULL,NULL,NULL),
